/* Quality costs capacity: presentation and oven timing feed the existing remake queue. */
function ovenQuality(s,time){const late=Math.max(0,time-s.started-s.duration);return {late,burned:late>=15,score:late<=8?100:late<15?Math.round(100-(late-8)*4):Math.max(10,Math.round(65-(late-15)*3))};}
const qualityCollect=QueueCafe.prototype.collectOven;
QueueCafe.prototype.collectOven=function(slot){const s=this.ovenSlots[slot];if(!s?.ready)return false;const o=this.orders.find(o=>o.id===s.id),q=this.tutorial?{score:100,burned:false,late:0}:ovenQuality(s,this.time);const ok=qualityCollect.call(this,slot);if(ok&&o){Object.assign(o.bakeryResult,q);this.lastFoodQuality=q;}return ok;};
function presentationFor(o){if(!o?.toppingStrokes?.length)return {score:0,note:'Add the requested toppings.'};let scores=[];for(const type of o.recipe.topping){const strokes=o.toppingStrokes.filter(s=>s.type===type);if(!strokes.length){scores.push(0);continue;}const points=strokes.flatMap(s=>s.points);if(type==='Cinnamon'){const p=points.at(-1);scores.push(p.x>=140&&p.x<=320&&p.y>=60&&p.y<=170?100:50);continue;}const xs=points.map(p=>p.x),ys=points.map(p=>p.y),width=Math.max(...xs)-Math.min(...xs),height=Math.max(...ys)-Math.min(...ys);const cream=type==='Whipped Cream'||type==='Cold Foam';let length=0;for(const s of strokes)for(let i=1;i<s.points.length;i++)length+=Math.hypot(s.points[i].x-s.points[i-1].x,s.points[i].y-s.points[i-1].y);const centered=Math.abs((Math.max(...xs)+Math.min(...xs))/2-230);const spill=points.filter(p=>p.x<132||p.x>328||p.y<35||p.y>173).length/points.length;const coverage=Math.min(1,width/(cream?100:95));const heightFactor=Math.min(1,height/(cream?45:28));const excess=Math.max(0,length-(cream?1200:1000))/45;const score=Math.max(0,Math.min(100,Math.round(60*coverage+40*heightFactor-Math.max(0,centered-35)*.7-spill*100-excess)));scores.push(score);}const score=Math.round(scores.reduce((a,b)=>a+b,0)/scores.length);return {score,note:score>=90?'Neat, balanced coverage.':score>=80?'Presentable! A little more even coverage can help.':'Spread toppings evenly over the cup. Undo spills or heavy scribbles.'};}
const qualityFinish=QueueCafe.prototype.finishToppings;
QueueCafe.prototype.finishToppings=function(o=this.active){const ok=qualityFinish.call(this,o);if(ok){o.presentationScore=this.tutorial?100:presentationFor(o).score;o.fills.topping=Math.min(o.fills.topping,o.presentationScore);}return ok;};
const qualityRetry=QueueCafe.prototype.retry;
QueueCafe.prototype.retry=function(k,o=this.active){const r=qualityRetry.call(this,k,o);if(o)delete o.presentationScore;return r;};
const QualityBase=CampaignCafe;
CampaignCafe=class extends QualityBase{
 serve(o=this.active,helper=false){if(!this.ready(o))return null;const score=this.scores(o).accuracy;const r=super.serve(o,helper);if(r){this.qualityAttempts??=[];this.qualityAttempts.push(score);}return r;}
 report(){const r=super.report();if(this.qualityAttempts?.length)r.quality=this.qualityAttempts.reduce((a,b)=>a+b,0)/this.qualityAttempts.length;return r;}
};
// Existing illustrated sprites plus the café's alternate character sheet.
const illustratedCharacter=character;
character=function(index,mood='happy',barista=false){if(barista||index<5)return illustratedCharacter(index,mood,barista);const roster=[{x:66,w:482,face:[298,392],skin:'#f7b97e'},{x:626,w:520,face:[883,372],skin:'#965c37'},{x:1260,w:462,face:[1490,389],skin:'#f5c183'}],c=roster[(index-5)%3],fx=c.face[0],fy=c.face[1];return `<svg viewBox="${c.x} 65 ${c.w} 760" aria-hidden="true"><image href="assets/customers.png" width="1792" height="896"/><g class="face-change"><ellipse cx="${fx}" cy="${fy}" rx="46" ry="22" fill="${c.skin}"/><path class="frown-mouth" d="M${fx-30} ${fy+8}Q${fx} ${fy-19} ${fx+30} ${fy+8}" fill="none" stroke="#4b2b19" stroke-width="6" stroke-linecap="round"/><path class="neutral-mouth" d="M${fx-24} ${fy}h48" stroke="#4b2b19" stroke-width="6" stroke-linecap="round"/></g></svg>`;};
// The same continuous curved path is used for cream, foam, and both sauces.
strokeArt=function(stroke){if(!stroke.points.length)return '';if(stroke.type==='Cinnamon')return priorStrokeArt(stroke);const d=smoothToppingPath(stroke.points),cream=stroke.type==='Whipped Cream',foam=stroke.type==='Cold Foam',caramel=stroke.type==='Caramel Drizzle',thick=cream||foam,w=cream?22:foam?28:6,color=cream?'#fff6e6':foam?'#f5fcff':caramel?'#d78a2c':'#68351f',edge=thick?'#d5bfa0':caramel?'#9f581b':'#412114';return `<g><path d="${d}" stroke="${edge}" stroke-width="${w+3}" fill="none" stroke-linejoin="round" stroke-linecap="round"/><path d="${d}" stroke="${color}" stroke-width="${w}" fill="none" stroke-linejoin="round" stroke-linecap="round"/><path d="${d}" stroke="${thick?'#fff':caramel?'#ffce7a':'#b67d54'}" stroke-width="${thick?5:1.6}" transform="translate(0 -${thick?4:1})" opacity=".8" fill="none" stroke-linejoin="round" stroke-linecap="round"/>${cream?`<path d="${d}" stroke="#ecdcc4" stroke-width="2" transform="translate(0 5)" fill="none" stroke-linecap="round"/>`:''}</g>`;};
toppingPoint=priorToppingPoint;
const qualityOpenToppings=openToppings;
openToppings=function(){qualityOpenToppings();if(stationPanel?.key!=='topping')return;document.querySelectorAll('#decoration-canvas [stroke-dasharray]').forEach(e=>e.remove());document.querySelector('.topping-legend').innerHTML='<b>Hold to dispense</b><span>Cream: swirl from wide to narrow</span><span>Foam: a soft, even layer</span><span>Sauce: sweep side to side</span><small>Keep it centered. Undo spills before finishing.</small><strong id="presentation-score" role="status"></strong>';drawToppings();};
const qualityDraw=drawToppings;
drawToppings=function(){qualityDraw();const o=sim?.orders.find(o=>o.id===stationPanel?.id),e=document.querySelector('#presentation-score');if(o&&e){const q=presentationFor({...o,toppingStrokes:[...(o.toppingStrokes||[]),...(toppingGesture?.points.length?[toppingGesture]:[])]});e.textContent=`Presentation: ${q.score}% · ${q.note}`;e.className=q.score>=80?'quality-good':'quality-low';}};
const qualityGesture=startToppingGesture;
startToppingGesture=function(ev,target){qualityGesture(ev,target);const ghost=document.querySelector('.topping-ghost');if(ghost&&toppingTool!=='Cinnamon'){ghost.classList.add('dispenser');ghost.classList.remove('sauce-bottle');ghost.dataset.kind=toppingTool;}};
const qualityBaking=updateBaking;
updateBaking=function(){qualityBaking();if(stationPanel?.key!=='baking'||sim.tutorial)return;document.querySelectorAll('[data-slot]').forEach(el=>{const s=sim.ovenSlots[+el.dataset.slot];const q=s?ovenQuality(s,sim.time):null;el.classList.toggle('food-burned',!!q?.burned);el.classList.toggle('food-warning',!!s?.ready&&!q.burned);if(s?.ready)el.querySelector('strong').textContent=q.burned?`BURNED · ${q.score}% quality · collect`:`Collect now · burns in ${Math.ceil(15-q.late)}s`;});const result=sim.orders.find(o=>o.id===stationPanel.id)?.bakeryResult;if(result)document.querySelector('#oven-feedback').textContent=`${result.burned?'Burned food':'Collected food'} · Quality ${result.score}%. ${result.score<90?'Use Remake, or the customer will return it.':'Ready to serve.'}`;};
const qualityOpenBaking=openBaking;
openBaking=function(){qualityOpenBaking();if(stationPanel?.key==='baking'&&!sim.tutorial)document.querySelector('.baking-dialog header small').textContent=`${sim.ovenSlots.length} slots · ${sim.upgrades.has('oven')?25:45}s bake · collect within 8s for perfect quality`;};
const qualityUpdate=update;
update=function(){qualityUpdate();if(!sim||sim.tutorial||sim.finished)return;document.querySelector('#baking-status').innerHTML=sim.ovenSlots.map((s,i)=>{if(!s)return '';const q=ovenQuality(s,sim.time);return `<span class="${q.burned?'quality-low':''}">Slot ${i+1} · ${sim.orders.find(o=>o.id===s.id)?.name}: ${s.ready?(q.burned?'BURNED — collect & remake':`Ready! Burns in ${Math.ceil(15-q.late)}s`):Math.ceil(s.duration-sim.time+s.started)+'s'}</span>`;}).join('');};
const qualityBegin=beginCampaignShift;
beginCampaignShift=function(){qualityBegin();document.querySelector('.learning-card p')?.insertAdjacentHTML('beforeend','<br><br><b>Quality matters:</b> collect food within 8 seconds of the timer finishing; it burns after 15 seconds. Keep toppings centered and evenly spread (80% presentation or better). Remakes use time and lower your quality result.');};
const qualityReport=showReport;
showReport=function(){qualityReport();};
// Cream tools are held cans with the nozzle directly above the deposited ribbon.
const dispenserGesture=startToppingGesture;
startToppingGesture=function(ev,target){dispenserGesture(ev,target);const ghost=document.querySelector('.topping-ghost');if(ghost&&['Whipped Cream','Cold Foam'].includes(toppingTool)){ghost.classList.add('cream-can');ghost.innerHTML=`<svg viewBox="0 0 64 100" aria-hidden="true"><path d="M17 9Q32 3 47 9V68Q32 77 17 68Z" fill="#fffaf1" stroke="#594837" stroke-width="2"/><path d="M17 15h30v15H17ZM17 51h30v13H17Z" fill="${toppingTool==='Cold Foam'?'#76b7c7':'#6089be'}"/><path d="M19 70l7 11h12l7-11Z" fill="#cbd0d2" stroke="#594837" stroke-width="2"/><path d="M29 81h6v14h-6Z" fill="#e7e8df" stroke="#594837" stroke-width="2"/><text x="32" y="43" text-anchor="middle" font-size="9" fill="#344c63">${toppingTool==='Cold Foam'?'FOAM':'CREAM'}</text></svg>`;}};
